{"action": "sql", "sql": "WITH skill AS (
  SELECT skill_id FROM skills.skills WHERE name = 'Stakeholder Management'
),
cycle AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE name = '2025-H1'
